// Theme bus: manages localStorage, applies CSS, bridges circuits via events.
const ThemeKey = 'app-theme';
const AccentKey = 'app-accent';

function applyTheme(theme) {
    const root = document.documentElement;
    root.setAttribute('data-theme', theme ?? 'System');
}

function applyAccent(color) {
    document.documentElement.style.setProperty('--accent-color', color || '#0d6efd');
}

function getTheme() {
    return localStorage.getItem(ThemeKey) || 'System';
}

function getAccent() {
    return localStorage.getItem(AccentKey) || '#0d6efd';
}

// Apply on first load (before any circuit connects)
applyTheme(getTheme());
applyAccent(getAccent());

// Dotnet references that want change notifications
const subscribers = new Set();

// Listen for storage events (cross-tab AND cross-circuit in same tab via BroadcastChannel)
const channel = new BroadcastChannel('theme-sync');

channel.onmessage = (e) => {
    applyTheme(e.data.theme);
    applyAccent(e.data.accent);
    notifySubscribers(e.data.theme, e.data.accent);
};

function notifySubscribers(theme, accent) {
    for (const ref of subscribers) {
        try {
            ref.invokeMethodAsync('OnThemeChangedFromJs', theme, accent);
        } catch {
            subscribers.delete(ref);
        }
    }
}

// Exported API called from .NET via JS interop
export function setTheme(theme, accent) {
    localStorage.setItem(ThemeKey, theme);
    localStorage.setItem(AccentKey, accent);
    applyTheme(theme);
    applyAccent(accent);
    channel.postMessage({ theme, accent });
    notifySubscribers(theme, accent);
}

export function getPreferences() {
    return { theme: getTheme(), accent: getAccent() };
}

export function subscribe(dotnetRef) {
    subscribers.add(dotnetRef);
}

export function unsubscribe(dotnetRef) {
    subscribers.delete(dotnetRef);
}

using Microsoft.JSInterop;

namespace sv_224df20eb1f24eafb8fd80b3412a5fc7.Services;

public enum ThemeMode { Light, Dark, System }

/// <summary>
/// Scoped service (one per circuit) that bridges .NET and the JS theme bus.
/// Multiple circuits share state through localStorage + BroadcastChannel.
/// </summary>
public sealed class ThemeService : IAsyncDisposable
{
    private readonly IJSRuntime _js;
    private IJSObjectReference? _module;
    private DotNetObjectReference<ThemeService>? _dotnetRef;
    private ThemeMode _theme = ThemeMode.System;
    private string _accent = "#0d6efd";

    public ThemeMode Theme => _theme;
    public string AccentColor => _accent;

    public event Action? OnChange;

    public ThemeService(IJSRuntime js)
    {
        _js = js;
    }

    public async Task InitializeAsync()
    {
        if (_module is not null) return;

        _module = await _js.InvokeAsync<IJSObjectReference>(
            "import", "./js/theme.js");

        var prefs = await _module.InvokeAsync<ThemePrefs>("getPreferences");
        _theme = Enum.TryParse<ThemeMode>(prefs.Theme, true, out var t) ? t : ThemeMode.System;
        _accent = prefs.Accent ?? "#0d6efd";

        _dotnetRef = DotNetObjectReference.Create(this);
        await _module.InvokeVoidAsync("subscribe", _dotnetRef);
    }

    public async Task SetThemeAsync(ThemeMode theme)
    {
        _theme = theme;
        await PushAsync();
    }

    public async Task SetAccentAsync(string accent)
    {
        _accent = accent;
        await PushAsync();
    }

    public async Task SetAllAsync(ThemeMode theme, string accent)
    {
        _theme = theme;
        _accent = accent;
        await PushAsync();
    }

    private async Task PushAsync()
    {
        if (_module is null) return;
        await _module.InvokeVoidAsync("setTheme", _theme.ToString(), _accent);
        OnChange?.Invoke();
    }

    // Called from JS when another circuit/tab changes the theme
    [JSInvokable]
    public void OnThemeChangedFromJs(string theme, string accent)
    {
        _theme = Enum.TryParse<ThemeMode>(theme, true, out var t) ? t : ThemeMode.System;
        _accent = accent ?? "#0d6efd";
        OnChange?.Invoke();
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null && _dotnetRef is not null)
        {
            try { await _module.InvokeVoidAsync("unsubscribe", _dotnetRef); } catch { }
        }
        _dotnetRef?.Dispose();
        if (_module is not null)
        {
            try { await _module.DisposeAsync(); } catch { }
        }
    }

    private record ThemePrefs(string Theme, string Accent);
}

@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeSvc.AccentColor;"
      title="Current theme: @ThemeSvc.Theme, Accent: @ThemeSvc.AccentColor">
    @icon @ThemeSvc.Theme
</span>

@code {
    private string icon => ThemeSvc.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ThemeSvc.InitializeAsync();
            ThemeSvc.OnChange += HandleChange;
            StateHasChanged();
        }
    }

    private void HandleChange() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeSvc.OnChange -= HandleChange;
}

