@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" style="max-width:200px"
            value="@ThemeSvc.Theme"
            @onchange="OnThemeSelected">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <option value="@mode" selected="@(mode == ThemeSvc.Theme)">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           value="@ThemeSvc.AccentColor"
           @onchange="OnAccentChanged" />
</div>

<div class="mt-4 p-3 border rounded" style="border-color: @ThemeSvc.AccentColor !important;">
    <strong>Preview:</strong> Current theme is <em>@ThemeSvc.Theme</em>
    with accent <span style="color:@ThemeSvc.AccentColor;">@ThemeSvc.AccentColor</span>.
</div>

@code {
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ThemeSvc.InitializeAsync();
            ThemeSvc.OnChange += HandleChange;
            StateHasChanged();
        }
    }

    private async Task OnThemeSelected(ChangeEventArgs e)
    {
        if (Enum.TryParse<ThemeMode>(e.Value?.ToString(), out var mode))
            await ThemeSvc.SetThemeAsync(mode);
    }

    private async Task OnAccentChanged(ChangeEventArgs e)
    {
        await ThemeSvc.SetAccentAsync(e.Value?.ToString() ?? "#0d6efd");
    }

    private void HandleChange() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeSvc.OnChange -= HandleChange;
}

